/* COMPLETE Print Format CSS - Fixes blank pages - CORRECTED */
/* Paste this into Print Format > Edit Properties > CSS */

/* Reduce page margins */
@page {
    size: A4;
    margin: 8mm 20mm 8mm 20mm;
}

/* Compact everything */
body {
    font-size: 9pt;
    line-height: 1.2;
}

/* Reduce all spacing */
.print-format h1, 
.print-format h2, 
.print-format h3 {
    margin: 3px 0;
    line-height: 1.1;
}

.print-format table td,
.print-format table th {
    padding: 2px 4px;
    font-size: 9pt;
    line-height: 1.2;
}

.print-format .row {
    margin-bottom: 3px;
}

/* CRITICAL: Compact Terms and Conditions to fit on one page */
.print-format .terms-and-conditions {
    font-size: 7.5pt !important;
    line-height: 1.1 !important;
    margin: 5px 0 0 0 !important;
    padding: 0 !important;
}

.print-format .terms-and-conditions ul,
.print-format .terms-and-conditions ol {
    margin: 2px 0 !important;
    padding-left: 15px !important;
}

.print-format .terms-and-conditions li {
    margin: 1px 0 !important;
    padding: 0 !important;
    line-height: 1.1 !important;
}

.print-format .terms-and-conditions h4,
.print-format .terms-and-conditions h5 {
    font-size: 8pt !important;
    margin: 3px 0 2px 0 !important;
}

/* Compact payment summary */
.payment-summary {
    margin: 5px 0 !important;
}

/* Make item descriptions more compact */
.print-format .item-table td {
    line-height: 1.15;
}

/* Reduce header/logo area if needed */
.print-format .print-heading {
    margin-bottom: 5px;
}

/* Reduce spacing around all divs to prevent overflow */
.print-format div {
    margin-bottom: 3px;
}

